window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5cbec6f737b88ecc"]={"versions": [{"id": "FIG-5cbec6f737b88ecc", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im Kontext des AUTOSAR Software Component Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm modelliert die Zuordnung von Datentyp- und Konstantendefinitionen zu einer Software-Kompositionsstruktur (<code>CompositionSwComponentType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Modellelemente und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>CompositionSwComponentType</code>: Spezialisierung bzw. Ausprägung von <code>SwComponentType</code> (oben rechts als Basistyp kursiv vermerkt).\n</li><li><code>Datatypes::DataTypeMappingSet</code>: Element mit den Stereotypen/Spezialisierungen <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li><li><code>Constants::ConstantSpecificationMappingSet</code>: Element mit dem Typvermerk <code>ARElement</code>.\n</li></ul>\n<p class=\"fig-p\">Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>CompositionSwComponentType</code> referenziert über die gerichtete Assoziation <code>+dataTypeMapping</code> mit der Kardinalität <code>0..*</code> die Zielklasse <code>Datatypes::DataTypeMappingSet</code>.\n</li><li><code>CompositionSwComponentType</code> referenziert über die gerichtete Assoziation <code>+constantValueMapping</code> mit der Kardinalität <code>0..*</code> die Zielklasse <code>Constants::ConstantSpecificationMappingSet</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Sequenzen, Kontrollflüsse oder Laufzeitübergänge dar. Die Beziehungen spezifizieren statische Referenzen innerhalb der Modellierungsphase.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>CompositionSwComponentType</code> kann optional mehrere Datentyp-Mappings (<code>DataTypeMappingSet</code>) sowie konstante Wertemappings (<code>ConstantSpecificationMappingSet</code>) referenzieren (jeweils Multiplizität <code>0..*</code>). Beide Mapping-Sets sind eigenständige <code>ARElement</code>-Instanzen. <code>Datatypes::DataTypeMappingSet</code> unterstützt zudem das AUTOSAR-Blueprint-Konzept (<code>AtpBlueprint</code>, <code>AtpBlueprintable</code>).</p>"}, {"id": "FIG-f9fe096446e406c6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im Kontext des AUTOSAR Software Component Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm modelliert die Zuordnung von Datentyp- und Konstantendefinitionen zu einer Software-Kompositionsstruktur (<code>CompositionSwComponentType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Modellelemente und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>CompositionSwComponentType</code>: Spezialisierung bzw. Ausprägung von <code>SwComponentType</code> (oben rechts als Basistyp kursiv vermerkt).\n</li><li><code>DataTypeMappingSet</code>: Element mit den Typvermerken <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li><li><code>ConstantSpecificationMappingSet</code>: Element mit dem Typvermerk <code>ARElement</code>.\n</li></ul>\n<p class=\"fig-p\">Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>CompositionSwComponentType</code> referenziert über die gerichtete Assoziation <code>+dataTypeMapping</code> mit der Kardinalität <code>0..*</code> die Zielklasse <code>DataTypeMappingSet</code>.\n</li><li><code>CompositionSwComponentType</code> referenziert über die gerichtete Assoziation <code>+constantValueMapping</code> mit der Kardinalität <code>0..*</code> die Zielklasse <code>ConstantSpecificationMappingSet</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Sequenzen, Kontrollflüsse oder Laufzeitübergänge dar. Die Beziehungen spezifizieren statische Referenzen innerhalb der Modellierungsphase.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>CompositionSwComponentType</code> kann optional mehrere Datentyp-Mappings (<code>DataTypeMappingSet</code>) sowie konstante Wertemappings (<code>ConstantSpecificationMappingSet</code>) referenzieren (jeweils Multiplizität <code>0..*</code>). Beide Mapping-Sets sind eigenständige <code>ARElement</code>-Instanzen. <code>Datatypes::DataTypeMappingSet</code> unterstützt zudem das AUTOSAR-Blueprint-Konzept (<code>AtpBlueprint</code>, <code>AtpBlueprintable</code>).</p>"}], "trans": [{"from": "FIG-5cbec6f737b88ecc", "to": "FIG-f9fe096446e406c6", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>Datatypes::DataTypeMappingSet</code>: Paketpräfix <code>Datatypes::</code> entfernt, Klasse ist nun als <code>DataTypeMappingSet</code> bezeichnet.\n</li><li><code>Constants::ConstantSpecificationMappingSet</code>: Paketpräfix <code>Constants::</code> entfernt, Klasse ist nun einzeilig als <code>ConstantSpecificationMappingSet</code> bezeichnet.\n</li></ul>"}]};
